export type Locale = keyof typeof messages;
export type MessageKey = keyof (typeof messages)["en"];
export function isMessageKey(value: string): value is MessageKey {
  return Object.hasOwn(messages.en, value);
}
export const languages: { value: Locale; label: string }[] = [
  { value: "zh-CN", label: "简体中文" },
  { value: "zh-TW", label: "繁體中文" },
  { value: "en", label: "English" },
  { value: "ja", label: "日本語" },
  { value: "ko", label: "한국어" },
  { value: "fr", label: "Français" },
  { value: "es", label: "Español" },
  { value: "de", label: "Deutsch" },
];
export function resolveLocale(value: string | null | undefined): Locale {
  const normalized = value?.toLowerCase().replaceAll("_", "-") ?? "";
  if (/^zh-(tw|hk|mo|hant)(-|$)/.test(normalized)) return "zh-TW";
  if (normalized === "zh" || normalized.startsWith("zh-")) return "zh-CN";
  const base = normalized.split("-")[0];
  return (
    languages.find((language) => language.value === base)?.value ?? "zh-CN"
  );
}
export function translate(
  locale: Locale,
  key: MessageKey,
  params: Record<string, string | number> = {},
) {
  // Runtime-installed locales are not keys in the static source dictionary.
  const localized = messages[locale] as Partial<Record<MessageKey, string>> | undefined;
  const template = localized?.[key] ?? messages.en[key] ?? key;
  return template.replace(
    /\{(\w+)\}/g,
    (placeholder: string, name: string) => String(params[name] ?? placeholder),
  );
}
